import unittest
from collections import deque
class Check(unittest.TestCase):
    def test_control(self):
        self.assertEqual(list(deque('abc', 2)), ['b','c'])
        self.assertEqual(list(deque([1])), [1])
if __name__ == '__main__':
    unittest.main()

